using System;using System.Drawing;using System.Reflection;using System.Collections;using System.Windows.Forms;
class IngredientHoverChecks{[STAThread]static void Main(){using(var f=new Form())using(var v=new IngredientLedgerView()){f.ClientSize=new Size(1280,780);v.Dock=DockStyle.Fill;f.Controls.Add(v);f.Show();Application.DoEvents();using(var b=new Bitmap(v.Width,v.Height))v.DrawToBitmap(b,v.ClientRectangle);var items=(IEnumerable)typeof(IngredientLedgerView).GetField("hoverItems",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(v);bool dish=false,ingredient=false;foreach(var item in items){var t=item.GetType();string title=(string)t.GetField("Title").GetValue(item);if(title!="黄油煎蛋")continue;var r=(Rectangle)t.GetField("Area").GetValue(item);typeof(IngredientLedgerView).GetMethod("OnMouseMove",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(v,new object[]{new MouseEventArgs(MouseButtons.None,0,r.X+r.Width/2,r.Y+r.Height/2,0)});if(typeof(IngredientLedgerView).GetField("hovered",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(v)==null)throw new Exception("missing hover");using(var b=new Bitmap(v.Width,v.Height)){v.DrawToBitmap(b,v.ClientRectangle);b.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,title=="黄油"?"ingredient-hover.png":"dish-hover.png"));}if(title=="黄油")ingredient=true;else dish=true;break;}if(!dish)throw new Exception("missing dish hover");Console.WriteLine("PASS dish hover hit area and rendering");}}}
